{
  "name": "omo-olympus",
  "version": "0.2.13",
  "description": "Greek mythology personas for opencode agents — watch Sisyphus, Oracle, and friends narrate your AI workflow in the sidebar",
  "author": "orca",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/akasai/omo-olympus.git"
  },
  "homepage": "https://github.com/akasai/omo-olympus#readme",
  "type": "module",
  "scripts": {
    "test": "vitest run",
    "test:watch": "vitest"
  },
  "exports": {
    "./server": "./src/server.ts",
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src/tui.tsx",
    "src/server.ts"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "oh-my-opencode",
    "tui-plugin",
    "agent-persona",
    "greek-mythology"
  ],
  "devDependencies": {
    "vitest": "4.1.4"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.4.3"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    }
  }
}
